def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    hat_patches = image_patch.find("hat")
    bench_patches = image_patch.find("bench")
    guy_patches = image_patch.find("guy")

    if not hat_patches or not bench_patches or not guy_patches:
        return image_patch

    min_distance = float('inf')
    target_hat = None

    for hat in hat_patches:
        for bench in bench_patches:
            for guy in guy_patches:
                dist_h_b = distance(hat, bench)
                dist_b_g = distance(bench, guy)
                dist_h_g = distance(hat, guy)

                if dist_h_b < 0 or dist_b_g < 0 or dist_h_g < 0:
                    continue

                total_dist = abs(dist_h_b) + abs(dist_b_g) + abs(dist_h_g)

                if total_dist < min_distance:
                    min_distance = total_dist
                    target_hat = hat

    return target_hat

