def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    shirt_patches = image_patch.find("shirt")

    if not boy_patches or not shirt_patches:
        return image_patch

    boy = boy_patches[0]
    shirt = shirt_patches[0]

    if boy.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
        return shirt

    shirt_center_x = (shirt.left + shirt.right) / 2
    shirt_center_y = (shirt.lower + shirt.upper) / 2

    boy_center_x = (boy.left + boy.right) / 2
    boy_center_y = (boy.lower + boy.upper) / 2

    if abs(shirt_center_x - boy_center_x) < abs(shirt_center_y - boy_center_y):
        if shirt_center_x > boy_center_x:
            return shirt
        else:
            return image_patch.crop(shirt.left, shirt.lower, shirt.right, shirt.upper)
    else:
        if shirt_center_y > boy_center_y:
            return shirt
        else:
            return image_patch.crop(shirt.left, shirt.lower, shirt.right, shirt.upper)

